mapper.select:
SELECT capability_code FROM cage_region_capability
WHERE region_type = #{regionType} AND region_id = #{regionId}
  AND configured_by <=> #{configuredBy}
  AND enabled = 1
ORDER BY capability_code ASC

mapper.delete:
DELETE FROM cage_region_capability
WHERE region_type = #{regionType} AND region_id = #{regionId}
  AND configured_by <=> #{configuredBy}
